+    }
+
+    @Override
+    public int hashCode() {
+        return delegate.hashCode();
+    }
+
+    @Override
+    public String toString() {
+        return delegate.toString();
+    }
+
+    private Path toDelegate(Path path) {
+        if (path instanceof QuotaAwarePath) {
