+        for (int i = 0; i < shards.size(); i++) {
+            consumer.consumeResult(shards.get(i), () -> latch.countDown());
+        }
+        latch.await();
+        SearchPhaseController.ReducedQueryPhase phase = consumer.reduce();
+        executor.shutdownNow();
+        return phase;
+    }
+}
