+        return new ClearApiKeyCacheRequest();
+    }
+    
+    public static ClearApiKeyCacheRequest clearById(String ... ids) { 
+        if (ids.length == 0) {
+            throw new IllegalArgumentException("Ids cannot be empty");
+        }  
+        return new ClearApiKeyCacheRequest(ids);
+     }
